// Дата отсчёта "выполнено" (этап выполнен, если есть факт-дата <= сегодня)
export const PIR_TODAY = new Date();
PIR_TODAY.setHours(0, 0, 0, 0);

export const pirIsDone = (factIso) => {
  if (!factIso) return false;
  const d = new Date(factIso + 'T00:00:00');
  return !isNaN(d.getTime()) && d <= PIR_TODAY;
};

// Разворачиваем компактные данные в полную структуру
export const PIR_ROUTES_DATA = PIR_RAW.map(r => ({
  id: r.id,
  name: r.name,
  region: r.region,
  district: r.district,
  branch: r.branch,
  km: r.km,
  stages: r.st.map((pf, i) => ({
    name: PIR_STAGE_NAMES[i] || ('Этап ' + (i + 1)),
    planDate: pf[0] || null,
    factDate: pf[1] || null,
    done: pirIsDone(pf[1]),
  })),
}));

export function parseVolsSheet(rows) {
  function toDate(v) {
    if (!v) return null;
    if (v instanceof Date) return v.toISOString().slice(0, 10);
    const s = String(v).trim();
    return s.length >= 10 ? s.slice(0, 10) : null;
  }
  function toBranch(v) {
    const s = String(v || '').toLowerCase();
    if (s.includes('красн')) return 'red';
    if (s.includes('зелен')) return 'green';
    if (s.includes('синя') || s.includes('голуб')) return 'blue';
    return 'red';
  }
  const manualPct = { green: null, blue: null, red: null, overall: null };
  rows.forEach(r => {
    if (!r || !r[1]) return;
    const label = String(r[1]).toLowerCase().trim();
    const fromC = String(r[2] || '').replace('%', '').replace(',', '.').trim();
    const fromE = String(r[4] || '').replace('%', '').replace(',', '.').trim();
    const pct = parseFloat(fromC) || parseFloat(fromE) || null;
    if (pct == null) return;
    if (label.includes('общ')) manualPct.overall = pct;
    else if (label.includes('зелен')) manualPct.green = pct;
    else if (label.includes('синя') || label.includes('голуб')) manualPct.blue = pct;
    else if (label.includes('красн')) manualPct.red = pct;
  });

  // ✅ ИЗМЕНИ: было "return rows.slice(3)", стало "const routes = rows.slice(3)"
  const routes = rows.slice(3)
    .filter(r => r[4] && r[5])
    .map((r, idx) => ({
      id: idx + 1,
      name: String(r[3] || r[2] || ''),
      region: String(r[0] || ''),
      district: String(r[1] || ''),
      branch: toBranch(r[4]),
      km: parseFloat(r[5]) || 0,
      stages: Array.from({ length: 21 }, (_, i) => ({
        name: PIR_STAGE_NAMES[i] || ('Этап ' + (i + 1)),
        planDate: toDate(r[9 + i * 2]) || null,
        factDate: toDate(r[9 + i * 2 + 1]) || null,
        done: pirIsDone(toDate(r[9 + i * 2 + 1])),
      })),
    }));

  // ✅ ДОБАВЬ ЭТО вместо старого закрывающего });
  return { routes, manualPct };
}

